"""An English synthetic equity fixture with auditable local exhibits.
Uses the imported valuation engine and report renderer; does not fetch market data.
"""
import copy
import importlib.util
import json
import re
import sys
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
OUT=Path(sys.argv[1]).resolve()
PACKAGE=ROOT/'catalogue-items/imported/equity-research-valuation-report-builder'
DATE='2026-10-22'
def save(path,obj):path.write_text(json.dumps(obj,indent=2,ensure_ascii=False),encoding='utf-8')
def evidence(text,ids=['S01']):return dict(text=text,source_ids=ids)

v=json.loads((PACKAGE/'tests/fixtures/standard-valuation-input.json').read_text(encoding='utf-8'))
v['market'].update(as_of=DATE,price_as_of=DATE,current_price=12,diluted_shares=10)
v['bridge'].update(excess_cash=20,debt=30)
v['relative_cross_checks'][0].update(value=140,note='Synthetic EV/FCF cross-check: 9.3333 x $15m FCFF = $140m EV; $13/share after bridge.')
for name,price in [('bear',8),('base',14),('bull',20)]:v['scenarios']['items'][name]['exit_value']=price
v['reverse_valuation']['forward_price']=14
save(OUT/'inputs/valuation-input.json',v)

c=json.loads((PACKAGE/'tests/fixtures/standard-report.json').read_text(encoding='utf-8'))
c['meta'].update(company_name='Sample Systems | SYNTHETIC',ticker='SAMPLE',exchange='Not listed - simulation only',as_of=DATE,language='en')
c['summary']=dict(headline='A $14 sample value leaves too little cushion at $12.',one_line_judgment='Synthetic scenario only: $15m flat annual FCFF supports $14 per share at a 10% WACC; a 20% cushion requires $11.20.',investment_posture='Sample decision: wait',posture_rationale='The illustrative $12 price exceeds the $11.20 threshold. No real security or trade is evaluated.',overall_confidence='low',maximum_unknown='All operating and market inputs are assumed.',company_quality='A fictional subscription service with flat $100m revenue and a 20% operating margin; no evidence of a durable moat.',stock_value='Calculated enterprise value $150m plus $20m cash less $30m debt gives $140m equity, or $14 per diluted share.')
c['evidence_scope']=dict(source_coverage='Five local synthetic exhibits exercise source roles. They provide no external corroboration and are not real filings, interviews, surveys or prices.',primary_filing_status='synthetic fixture',earnings_call_status='synthetic fixture',industry_evidence_status='synthetic fixture',research_confidence='low',conflicts_and_gaps='Every input is assumed for QA. Industry and peer statements are counterfactual sample exhibits, not independent research.',evidence_blocks=[dict(kind=k,text=t,source_ids=ids,confidence='low') for k,t,ids in [('fact','Within the sample ledger, annual revenue is $100m; this is not an observed company fact.',['S01']),('management-view','The fictional management case assumes stable renewal demand.',['S01']),('market-view','The fictional peer case describes discount pressure.',['S02']),('calculation','FCFF = $100m x 20% x (1 - 25%) = $15m; D&A, capex and NWC changes are set to zero.',['S01']),('inference','Flat demand may be compatible with stable cash flow, but no real evidence establishes it.',['S01','S05'])]])
c['business']=dict(model_and_demand='The sample business sells workflow subscriptions. Revenue is held flat by design; no claim is made about an actual market.',value_creation='The test assumes recurring cash receipts without growth investment.',industry_stage_and_drivers='This fixture supplies a mature, flat-demand setting solely to isolate valuation arithmetic.',competitive_position='The sample peer offers a similar product. Pricing pressure is a scenario risk.',moats=[dict(title='Workflow integration',**evidence('Potential switching friction is an unverified sample hypothesis.')),dict(title='Recurring contracts',**evidence('Contract persistence is assumed, not measured.'))],counter_evidence=evidence('A fictional competitor discounts its equivalent product.',['S02','S05']),industry_validation=dict(claim='The synthetic market is stable, with pricing pressure.',company=evidence('Fictional company case: flat demand.'),competitors=[evidence('Fictional peer case: flat demand with discounting.',['S02'])],independent=dict(**evidence('Synthetic industry exhibit assumes flat demand; it is not independent external evidence.',['S03']),status='available',reason='Local test exhibit only.'),agreement_or_conflict='Demand assumptions agree; margin durability remains uncertain.',confidence='low',gap='No real company, peer or industry data were obtained.'))
c['management']=dict(overview='Fictional management holds the cash-flow model flat. Capital allocation quality cannot be assessed from these synthetic exhibits.',mda_delta=[dict(topic=topic,previous_period=prev,current_period=now,change='0',interpretation='Stable by construction.',source_ids=['S01'],alternative_explanation='Synthetic inputs explain the stability.',validation_task='Replace with audited period disclosures before real analysis.') for topic,prev,now in [('Revenue','$100m','$100m'),('Operating margin','20%','20%'),('Annual FCFF','$15m','$15m')]],promises=[dict(id='P01',promise='Synthetic management goal: keep annual FCFF at $15m.',promise_date='2026-02-20',original_wording_locator='S01 / management_goal',due_date='2026-12-31',actual_result='Sample H1 FCFF is $7.5m; full year not yet observed.',source_ids=['S01'],status='pending',assessment='The future full-year outcome is not evidence of delivery.')])
f=c['financials'];f.update(overview='Flat synthetic operating statements; all financial amounts are USD millions except per-share values.',earnings_quality='The model sets D&A and capex to zero to isolate FCFF arithmetic. This is a restrictive test assumption, not a normal operating-company claim.',kpi_inflections='No measured inflection: all sample annual and quarterly operating values are flat.',sector_kpis=[dict(metric='Net retention',current='100% assumed',direction='flat',source_ids=['S01'])])
f['metric_continuity']=[dict(metric=x,periods='2023A-2026Q2',definition_scope_change='None; synthetic same-scope ledger',comparability_status='comparable',adjustment='None',source_ids=['S01']) for x in ['Revenue','Operating margin','Operating cash flow','FCFF','ROIC']]
def period(p,rev,ocf,fcff,growth):return dict(period=p,revenue=str(rev),growth=growth,margin='20%',ocf=str(ocf),fcf=str(fcff),roic='15% assumed',earnings_quality_note='Synthetic; FCFF equals NOPAT.',source_ids=['S01'])
f['annual_history']=[period(p,100,15,15,'0%') for p in ['2023A','2024A','2025A']]
f['quarterly_history']=[period(p,25,3.75,3.75,'0%') for p in ['2025Q3','2025Q4','2026Q1','2026Q2']]
c['valuation_context']=dict(route='dcf',method_rationale='Five-year FCFF DCF at 10% WACC and zero terminal growth. Flat $15m cash flows give a hand-checkable perpetuity value. The relative cross-check is another assumed benchmark.',assumptions=[dict(id=i,assumption=n,value=val,source_ids=[src]) for i,n,val,src in [('A01','WACC','10% analyst assumption','S04'),('A02','Terminal growth','0% analyst assumption','S03'),('A03','Terminal ROIC','15% assumed; no growth reinvestment required','S01')]],scenario_rationales={name:dict(operating_assumptions=op,valuation_assumptions=val,trigger_or_falsifier=trig) for name,op,val,trig in [('bear','Margin falls to 12%; other assumptions flat.','$9m FCFF / 10% less $10m net debt gives $8/share.','Replace base if sample operating margin falls to 12%.'),('base','Margin stays at 20%; revenue remains $100m.','$15m FCFF / 10% less $10m net debt gives $14/share.','Flat demand and margin remain the assumed case.'),('bull','Margin rises to 28%; other assumptions flat.','$21m FCFF / 10% less $10m net debt gives $20/share.','Requires sample operating margin at 28%.')]},reverse_interpretation='Reverse DCF holds the model structure fixed; any implied parameter is conditional and not a unique market forecast.',reconciliation_note='Primary EV $150m + cash $20m - debt $30m = equity $140m; divided by 10m shares = $14. Relative EV $140m gives $13/share after the same bridge.')
c['theses']=[dict(id=i,statement=stmt,supporting_source_ids=support,counter_source_ids=['S05'],evidence_types=['calculation','inference'],confidence='low',needs_validation=need) for i,stmt,support,need in [('T01','The sample flat-demand case sustains $100m revenue.',['S01','S03'],'Real renewal and demand evidence.'),('T02','A 20% margin and 25% cash tax yield $15m FCFF under zero investment changes.',['S01'],'Real capex, working capital and tax disclosures.'),('T03','At $12, the sample price lacks the required 20% cushion to $14 value.',['S04'],'Replace the synthetic price, WACC and operating forecasts.')]]
c['risks_and_breakers']=dict(summary='Unobserved inputs dominate confidence. The following rules link sample changes to model consequences.',breakers=[dict(breaker=b,trigger=t,confirmation_window='Next sample model revision',thesis_ids=[th],scenario_probability_impact='Re-estimate assumed probabilities; no automatic change.',valuation_impact=impact,research_action='Rebuild using verified source data.') for b,t,th,impact in [('Demand deterioration','Revenue below $100m','T01','Lower cash flows.'),('Margin deterioration','Operating margin at 12%','T02','Bear value becomes $8/share.'),('Price increase','Price above $14','T03','Discount to base value disappears.')]])
for key,value in c['scorecard'].items():value.update(score=2,confidence='low',rationale_or_gap='Synthetic; no external corroboration.')
c['monitoring']=[dict(metric=metric,current_value=current,as_of=DATE,source_ids=[src],next_update='Next sample data revision',bull_threshold=bull,bear_threshold=bear,thesis_ids=[th],valuation_impact=impact,research_action='Replace assumed inputs with verified period data.') for metric,current,src,bull,bear,th,impact in [('Revenue','$100m assumed','S01','Above $100m','Below $100m','T01','Changes forecast revenue.'),('Operating margin','20% assumed','S01','28%','12%','T02','Changes annual FCFF.'),('Industry demand','Flat assumed','S03','Growing','Shrinking','T01','Changes growth assumption.'),('Peer pricing','Stable assumed','S02','Higher','Lower','T01','Changes margin assumption.'),('Sample price','$12, not a quote','S04','At or below $11.20','Above $14','T03','Changes discount to value.')]]
c['conclusion']=dict(decision='Sample wait decision: $12 is above the $11.20 threshold. No actual security or investor is assessed.',company_quality='Insufficient evidence: all company inputs are synthetic.',stock_value='Base arithmetic gives $14/share, with a sample $8-$20 scenario range.',margin_of_safety_rationale='20% discount to $14 is $11.20; 35% discount is $9.10. Current discount to value is 14.2857%; price upside is 16.6667%, a different denominator.',validation_items=['Verify operating statements','Verify cash and debt','Verify fully diluted shares','Verify current price and risk assumptions'],thesis_ids=['T01','T02','T03'])
names=['Company ledger and assumptions','Peer scenario exhibit','Industry scenario exhibit','Price and discount-rate assumptions','Counter-evidence and limitations']
(OUT/'artifacts/sources').mkdir(exist_ok=True)
for idx,source in enumerate(c['sources']):
    sid=source['id'];name=f'{sid}.json'
    source.update(document='SYNTHETIC: '+names[idx],publication_date=DATE,reporting_period='Synthetic FY2023-2026Q2; forward assumptions 2027-2031',locator='Section 1 / JSON root and named fields',url_or_path='http://127.0.0.1:5197/sources/'+name,access_date=DATE)
    exhibit=dict(label='SYNTHETIC QA EXHIBIT; not an actual filing, survey, quotation or independent source',id=sid,as_of=DATE,role=source['role'])
    if sid=='S01':exhibit.update(financials=f,management=c['management'],business=c['business'],valuation_assumptions=v)
    elif sid=='S02':exhibit.update(demand='flat assumed',pricing='discount pressure assumed',peer='Fictional peer only')
    elif sid=='S03':exhibit.update(demand='flat assumed',independence='No external corroboration; test role only')
    elif sid=='S04':exhibit.update(price=12,price_type='fictional assumption, not market quote',wacc=.1,diluted_shares_million=10)
    else:exhibit.update(limitations=['Every input is synthetic','Capex and NWC held at zero','No external verification or moat evidence','Probabilities are analyst sample assumptions'])
    save(OUT/'artifacts/sources'/name,exhibit)
save(OUT/'inputs/equity-content.json',c)
print('Created synthetic English content, valuation input and five local source exhibits.')
